/**
 * app-shaker-form.js: Shaker Consultancy "طلب فحص واستلام" record PDF (Arabic, right to left).
 *
 * Used for the activity checklists whose code is like "04 22 00-1" / "09 24 00-3" (masonry and plaster activities).
 * Every other checklist keeps the English record made by PtahRecord. This file wraps PtahRecord.build:
 * if the checklist code has the form "NN NN NN-k", it draws the Shaker form; otherwise it calls the old build.
 * Same data in (PtahRecord.prepare), same bytes out. In Node (for samples) module.exports = { build }.
 */
(function (root) {
  const LIB = {
    pdfLib:  'https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js',
    fontkit: 'https://cdn.jsdelivr.net/npm/@pdf-lib/fontkit@1.1.1/dist/fontkit.umd.min.js',
    bidi:    'https://cdn.jsdelivr.net/npm/bidi-js@1.1.0/dist/bidi.min.js',
    reg:     'https://cdn.jsdelivr.net/npm/@expo-google-fonts/cairo@0.4.2/400Regular/Cairo_400Regular.ttf',
    bold:    'https://cdn.jsdelivr.net/npm/@expo-google-fonts/cairo@0.4.2/700Bold/Cairo_700Bold.ttf',
    xbold:   'https://cdn.jsdelivr.net/npm/@expo-google-fonts/cairo@0.4.2/800ExtraBold/Cairo_800ExtraBold.ttf'
  };
  const AR_RE = /[؀-ۿݐ-ݿࢠ-ࣿﭐ-﷿ﹰ-﻿]/;
  const FORM_CODE = /^\d\d \d\d \d\d-\d+$/;
  const LOGO_B64 = '';

  const W = 595.28, H = 841.89, ML = 34, CW = W - 2 * ML, FR = 14;       // page, side margin, content width, frame inset
  const INK = [0x1d, 0x27, 0x33], SUB = [0x55, 0x66, 0x77], MUTE = [0x88, 0x99, 0x99], LINE = [0xcf, 0xd6, 0xde], HAIR = [0xe3, 0xe7, 0xec],
        ORANGE = [0xc8, 0x64, 0x2d], CARD = [0xf4, 0xf6, 0xf8], CLAUSE = [0x3d, 0x5a, 0x80], WHITE = [255, 255, 255],
        OKC = [0x2e, 0x7d, 0x4f], BADC = [0xc0, 0x39, 0x2b], BADBG = [0xfd, 0xec, 0xea], RESBG = [0xff, 0xf4, 0xe8], RESINK = [0xb8, 0x56, 0x1c];
  const PTAH_B64 = '';
  const RESULT_AR = { A: 'مقبول', B: 'مقبول مع ملاحظات', C: 'مراجعة وإعادة تقديم', D: 'مرفوض' };
  const STAGE_AR = { 'Submittals & Approvals': 'المستندات والاعتمادات', 'Materials & Storage': 'المواد والتخزين', 'Before Work': 'قبل التنفيذ', 'During Work': 'أثناء التنفيذ', 'Tolerances': 'التفاوتات', 'Testing & Acceptance': 'الاختبارات والاستلام', 'Fabrication': 'التصنيع', 'Treatment': 'المعالجة' };

  const FLOORS = { ground: 'الأرضي', first: 'الأول', second: 'الثاني', third: 'الثالث', roof: 'السطح', 'upper roof': 'السطح العلوي',
                   basement: 'البدروم', mezzanine: 'الميزانين', all: 'كل الأدوار' };
  const b64 = s => { s = String(s || '').replace(/^data:[^,]*,/, ''); if (typeof atob === 'function') { const t = atob(s), u = new Uint8Array(t.length); for (let i = 0; i < t.length; i++) u[i] = t.charCodeAt(i); return u; } return Uint8Array.from(Buffer.from(s, 'base64')); };

  function isFormCode(d) { return !!(d && d.cl && FORM_CODE.test(String(d.cl.code))); }

  // where: "الدور" (floor) for indoor work, "الواجهة" (elevation) for facade work
  function whereOf(d) {
    const text = [d.activity, d.cl.title, d.floor].join(' ');
    const ext = /elevation|facade|façade|external|خارجي|واجهة/i.test(text) || /external|خارجي/i.test(d.cl.scope || '');
    const el = String(d.activity || '').match(/elevation\s*(?:no\.?\s*)?\(?\s*(\d+)\)?/i);
    const fl = String(d.floor || '').toLowerCase().replace(/\s*floors?$/, '').trim();
    const stair = /stair/i.test(d.activity || '') ? 'السلم' : '';
    const parts = [];
    if (el) parts.push('واجهة ' + el[1]);
    if (fl) parts.push(FLOORS[fl] || d.floor);
    if (stair) parts.push(stair);
    return { label: (ext && el) ? 'الواجهة / الموقع' : 'الدور / الموقع', value: parts.join(' - ') };
  }

  function loadScript(src) { return new Promise((ok, bad) => { const s = document.createElement('script'); s.src = src; s.onload = ok; s.onerror = () => bad(new Error('Could not load ' + src)); document.head.appendChild(s); }); }
  let libs = null;
  async function loadLibs() {
    if (libs) return libs;
    if (!root.PDFLib) await loadScript(LIB.pdfLib);
    if (!root.fontkit) await loadScript(LIB.fontkit);
    if (!root.bidi_js) await loadScript(LIB.bidi);
    const get = u => fetch(u).then(r => { if (!r.ok) throw new Error('Font download failed'); return r.arrayBuffer(); });
    const [reg, bold, xbold] = await Promise.all([get(LIB.reg), get(LIB.bold), get(LIB.xbold)]);
    return libs = { PDFLib: root.PDFLib, fontkit: root.fontkit, bidi: root.bidi_js(), reg, bold, xbold };
  }

  async function draw(L, d) {
    const { PDFDocument, rgb } = L.PDFLib;
    const doc = await PDFDocument.create();
    doc.registerFontkit(L.fontkit);
    const R = await doc.embedFont(L.reg, { subset: true });
    const B = await doc.embedFont(L.bold, { subset: true });
    const X = await doc.embedFont(L.xbold, { subset: true });
    const fk = L.fontkit.create(new Uint8Array(L.reg));
    const logo = await doc.embedPng(b64(LOGO_B64));
    let sigImg = null;
    if (d.signature) { try { sigImg = await doc.embedPng(b64(d.signature)); } catch (e) {} }
    const photos = [];
    for (const ph of (d.photos || [])) { try { photos.push({ img: await doc.embedJpg(b64(ph.data)), cap: ph.cap || '', tag: ph.tag || '' }); } catch (e) {} }

    // ---------- right-to-left text ----------
    function runs(s, f) {
      const lv = L.bidi.getEmbeddingLevels(s).levels, out = [];
      for (let i = 0; i < s.length; i++) {
        let ch = s[i];
        if (/[\uD800-\uDBFF]/.test(ch) && i + 1 < s.length) ch += s[++i];
        const lvl = lv[i];
        const ar = AR_RE.test(ch) || (lvl % 2 === 1 && !/[A-Za-z0-9]/.test(ch) && fk.hasGlyphForCodePoint(ch.codePointAt(0)));
        const last = out[out.length - 1];
        if (last && last.lvl === lvl && last.ar === ar) last.t += ch; else out.push({ t: ch, lvl, ar });
      }
      const max = Math.max(...out.map(r => r.lvl)), minOdd = Math.min(...out.map(r => r.lvl).filter(l => l % 2), 99);
      for (let k = max; k >= minOdd && k > 0; k--) {
        for (let i = 0; i < out.length; i++) {
          if (out[i].lvl < k) continue;
          let j = i; while (j + 1 < out.length && out[j + 1].lvl >= k) j++;
          out.splice(i, j - i + 1, ...out.slice(i, j + 1).reverse()); i = j;
        }
      }
      return out.map(r => {
        let t = r.t;
        const mirror = c => L.bidi.getMirroredCharacter(c) || c;
        if (r.lvl % 2 === 1) t = (r.ar && AR_RE.test(t)) ? [...t].map(mirror).join('') : [...t].reverse().map(mirror).join('');
        return { t, f };
      });
    }
    const col = a => rgb(a[0] / 255, a[1] / 255, a[2] / 255);
    const hasAr = s => AR_RE.test(String(s));
    const wid = (s, f, size) => hasAr(s) ? runs(String(s), f).reduce((a, r) => a + r.f.widthOfTextAtSize(r.t, size), 0) : f.widthOfTextAtSize(String(s), size);

    let page, y; const pages = [];
    function newPage() { page = doc.addPage([W, H]); pages.push(page); y = 0; }
    // text with its right edge at xr (Arabic), or left edge at xl when left = true
    function TR(s, xr, yy, f, size, c) { s = String(s); if (!s) return; const w = wid(s, f, size); TL(s, xr - w, yy, f, size, c); }
    function TL(s, x, yy, f, size, c) {
      s = String(s); if (!s) return;
      const base = { y: H - yy - size * 0.78, color: col(c || INK), size };
      if (!hasAr(s)) { page.drawText(s, Object.assign({ x, font: f }, base)); return; }
      runs(s, f).forEach(r => { page.drawText(r.t, Object.assign({ x, font: r.f }, base)); x += r.f.widthOfTextAtSize(r.t, size); });
    }
    function TC(s, xc, yy, f, size, c) { TL(s, xc - wid(s, f, size) / 2, yy, f, size, c); }
    const box = (x, yy, w, h, fill, stroke, bw) => page.drawRectangle({ x, y: H - yy - h, width: w, height: h,
      color: fill ? col(fill) : undefined, borderColor: stroke ? col(stroke) : undefined, borderWidth: stroke ? (bw || 0.7) : 0 });
    const hl = (x1, x2, yy, c, t, dash) => page.drawLine({ start: { x: x1, y: H - yy }, end: { x: x2, y: H - yy }, thickness: t || 0.6, color: col(c || LINE), dashArray: dash });
    const vl = (xx, y1, y2, c, t) => page.drawLine({ start: { x: xx, y: H - y1 }, end: { x: xx, y: H - y2 }, thickness: t || 0.6, color: col(c || LINE) });
    function wrap(s, f, size, maxW) {
      const out = [];
      String(s || '').split(/\n/).forEach(par => {
        let line = '';
        par.split(/\s+/).forEach(w => {
          if (!w) return;
          const t = line ? line + ' ' + w : w;
          if (wid(t, f, size) <= maxW) { line = t; return; }
          if (line) out.push(line);
          line = w;
        });
        out.push(line);
      });
      return out;
    }
    // check box with the mark inside: ok = tick, fail = cross, na = dash
    function check(x, yy, s, mark) {
      box(x, yy, s, s, WHITE, INK, 0.8);
      const c = mark === 'ok' ? OKC : mark === 'fail' ? BADC : INK;
      const seg = (a, b, c2, d2) => page.drawLine({ start: { x: x + a * s, y: H - yy - b * s }, end: { x: x + c2 * s, y: H - yy - d2 * s }, thickness: 1.6, color: col(c) });
      if (mark === 'ok') { seg(0.2, 0.55, 0.42, 0.78); seg(0.42, 0.78, 0.82, 0.22); }
      else if (mark === 'fail') { seg(0.22, 0.22, 0.78, 0.78); seg(0.78, 0.22, 0.22, 0.78); }
      else if (mark === 'na') seg(0.25, 0.5, 0.75, 0.5);
    }

    const RX = W - ML;
    const FOOT_Y = H - FR - 22;
    const room = () => FOOT_Y - 8 - y;
    const spaced = (s, xr, yy, f, size, c, gap) => { // Latin text with letter spacing, right edge at xr
      const w = [...s].reduce((a, ch) => a + wid(ch, f, size) + gap, -gap); let x = xr - w;
      for (const ch of s) { TL(ch, x, yy, f, size, c); x += wid(ch, f, size) + gap; } };
    function frame() { box(FR, FR, W - 2 * FR, H - 2 * FR, null, LINE, 0.7); }
    function header() {
      frame();
      const lw = 128, lh = lw * logo.height / logo.width;
      page.drawImage(logo, { x: RX - lw, y: H - 30 - lh, width: lw, height: lh });
      TL('مشروع ساوث ميد', ML, 33, X, 10.5, INK);
      TL('قوائم الفحص والاستلام للأعمال المعمارية', ML, 48, R, 7.4, SUB);
      hl(ML, RX, 66, LINE, 0.6);
      y = 80;
    }
    const L3 = d.cl.code.split("-")[0];

    function firstPage() {
      newPage(); header();
      // title block: division tag + code, big title on the right, request number on the left
      spaced(String(d.cl.division || '').toUpperCase(), RX, y, B, 6.5, ORANGE, 1.4); y += 11;
      TR(d.cl.code, RX, y, R, 8.4, SUB); y += 12;
      TR(d.cl.title, RX, y, X, 15.5, INK);
      const recTxt = (d.irNumber || '—') + ' · Rev ' + d.rev;
      TL('سجل فحص واستلام', ML, y - 22, R, 7, SUB);
      TL(recTxt, ML, y - 11, B, 11.5, INK);
      y += 30;
      if (d.cl.scope) { wrap(d.cl.scope, R, 7.6, CW - 170).forEach(l => { TR(l, RX, y, R, 7.6, SUB); y += 10; }); }
      y += 6;
      // request cards (first card on the right)
      const wh = whereOf(d), q = CW / 4;
      const rows = [
        [['المشروع', 'ساوث ميد', 1], ['المقاول', d.contractor || '—', 1], ['الفيلا / النوع', d.villa ? 'Villa ' + d.villa + (d.type ? ' · ' + d.type : '') : '—', 1], [wh.label.split(' / ')[0], wh.value || '—', 1]],
        [['النشاط', d.activity || '—', 2], ['رقم ACC', d.itemId || '—', 1], ['تاريخ الفحص', d.date || '—', 1]],
        [['المفتش', d.inspector || '—', 2], ['النتيجة', (d.code ? d.code + ' · ' : '') + (RESULT_AR[d.code] || ''), 2, true]]
      ];
      const nPh = (d.photos || []).length;
      if (d.weather || nPh || d.prevRev) rows.push([['الطقس عند الفحص', d.weather || '—', 2], ['الصور', nPh ? nPh + ' · في آخر الملف' : '—', 1], ['المراجعة السابقة', d.prevRev || '—', 1]]);
      rows.forEach(row => {
        const fsz = c => c[3] ? 10.5 : 8.6;
        const lines = row.map(c => wrap(c[1], B, fsz(c), q * c[2] - 14));
        const h = 18 + Math.max(...lines.map((l, i) => l.length * (row[i][3] ? 12.5 : 10.5)));
        let xr = RX;
        row.forEach((c, i) => {
          const wcell = q * c[2];
          box(xr - wcell, y, wcell, h, c[3] ? RESBG : null, LINE);
          TR(c[0], xr - 6, y + 4, R, 6.6, MUTE);
          lines[i].forEach((l, k) => TR(l, xr - 6, y + 13 + k * (c[3] ? 12.5 : 10.5), B, fsz(c), c[3] ? RESINK : INK));
          xr -= wcell;
        });
        y += h;
      });
      // the title exactly as written on ACC
      const tl = wrap(d.description || '', R, 7.8, CW - 14);
      if (tl.length && tl[0]) {
        const h = 18 + tl.length * 10;
        box(RX - CW, y, CW, h, null, LINE);
        TR('اسم التسليمة كما في ACC', RX - 6, y + 4, R, 6.6, MUTE);
        tl.forEach((l, k) => TR(l, RX - 6, y + 13 + k * 10, B, 7.8, INK));
        y += h;
      }
      // key values (cards with an orange bar on the right)
      if (d.cl.keyValues && d.cl.keyValues.length) {
        y += 12; TR('القيم الرئيسية', RX, y, B, 7.4, SUB); y += 12;
        const gap = 5, kw = (CW - 2 * gap) / 3;
        for (let i = 0; i < d.cl.keyValues.length; i += 3) {
          const row = d.cl.keyValues.slice(i, i + 3);
          const vals = row.map(k => wrap(k.value, B, 7.8, kw - 16));
          const h = 17 + Math.max(...vals.map(v => v.length)) * 9.6;
          row.forEach((k, j) => {
            const x = RX - (j + 1) * kw - j * gap;
            box(x, y, kw, h, CARD); box(x + kw - 2.4, y, 2.4, h, ORANGE);
            if (k.clause) TL(k.clause, x + 6, y + 4, R, 6, MUTE);
            TR(k.label, x + kw - 8, y + 4, R, 6.6, SUB);
            vals[j].forEach((l, n) => TR(l, x + kw - 8, y + 13.5 + n * 9.6, B, 7.8, INK));
          });
          y += h + gap;
        }
      }
    }

    // ---- checklist ----
    const hasClause = d.stages.some(st => st.items.some(it => it.clause));
    const XM = [ML + 4, ML + 22, ML + 40];                 // marks: dash, cross, tick (left side)
    const XCLR = ML + 46 + (hasClause ? 64 : 0);           // clause column right edge / start of text area on the left
    const TXT_R = RX - 18, TXT_W = TXT_R - (XCLR + 8);
    function tableHead() {
      TR('البند', TXT_R, y, R, 6.4, MUTE);
      if (hasClause) TL('البند في SPECS', ML + 48, y, R, 6.2, MUTE);
      [['—', 0], ['✗', 1], ['✓', 2]].forEach(m => { const sym = m[0]; mark(sym === '✓' ? 'ok' : sym === '✗' ? 'fail' : 'na', XM[m[1]] + 9, y + 4.2, 4.2, MUTE); });
      y += 10; hl(ML, RX, y, INK, 0.8); y += 1;
    }
    function mark(kind, cx, cy, r, c) {                    // tick / cross / dash drawn as lines, centred on (cx, cy from top)
      const seg = (a, b, c2, d2) => page.drawLine({ start: { x: cx + a * r, y: H - cy - b * r }, end: { x: cx + c2 * r, y: H - cy - d2 * r }, thickness: 1.5, color: col(c) });
      if (kind === 'ok') { seg(-1, 0.1, -0.35, 0.8); seg(-0.35, 0.8, 1, -0.9); }
      else if (kind === 'fail') { seg(-0.85, -0.85, 0.85, 0.85); seg(0.85, -0.85, -0.85, 0.85); }
      else seg(-0.8, 0, 0.8, 0);
    }
    function checklist() {
      y += 6;
      TR('قائمة الفحص', RX, y, B, 7.4, SUB);
      let lx = ML;
      [['ok', 'مطابق', OKC], ['fail', 'غير مطابق', BADC], ['na', 'لا ينطبق', MUTE]].forEach(g => {
        mark(g[0], lx + 4, y + 3.4, 3, g[2]); TL(g[1], lx + 11, y - 0.3, R, 6.6, SUB); lx += 11 + wid(g[1], R, 6.6) + 12;
      });
      y += 14; tableHead();
      let n = 0;
      d.stages.forEach(st => {
        const rows = st.items.map(it => wrap(it.text, R, 8.2, TXT_W));
        const hts = rows.map(r => Math.max(19, r.length * 10.6 + 8));
        if (room() < 40 + hts[0]) { newPage(); header(); tableHead(); }
        y += 7;
        const stTxt = (d.stages.length > 1 || !FORM_CODE.test(d.cl.code)) ? (STAGE_AR[st.heading] || st.heading) : 'بنود الفحص';
        if (d.stages.length > 1 || !FORM_CODE.test(d.cl.code)) { box(RX - 11, y - 1, 11, 11, INK); TC(st.key, RX - 5.5, y + 0.8, B, 7, WHITE); TR(stTxt, RX - 16, y + 0.8, B, 7.4, INK); }
        else TR(stTxt, RX, y + 0.8, B, 7.4, INK);
        TL(String(st.items.length), ML, y + 1.2, R, 6.6, MUTE);
        y += 13; hl(ML, RX, y, INK, 0.8);
        st.items.forEach((it, i) => {
          const h = hts[i];
          if (room() < h) { newPage(); header(); tableHead(); }
          if (it.mark === 'fail') box(ML, y, CW, h, BADBG);
          n++;
          TC(String(n), RX - 7, y + 5, R, 6.6, MUTE);
          rows[i].forEach((l, k) => TR(l, TXT_R, y + 4.4 + k * 10.6, R, 8.2, INK));
          if (it.clause) TL(it.clause, ML + 48, y + 5, B, 6.3, CLAUSE);
          const idx = { ok: 2, fail: 1, na: 0 }[it.mark];
          if (it.mark) mark(it.mark, XM[idx] + 9, y + h / 2, 4.6, it.mark === 'ok' ? OKC : it.mark === 'fail' ? BADC : MUTE);
          y += h; hl(ML, RX, y, HAIR, 0.6);
        });
      });
      y += 4;
    }

    function tail() {
      const sec = L3.replace(/ /g, ' ');
      const refs = sec === '09 24 00' ? 'القسم ' + sec + ' / ASTM C1861 / ASTM C1063 / ASTM C926.' : 'الرسومات التنفيذية المعتمدة / القسم ' + sec + ' / خطة الفحص والاختبار.';
      const noteLines = wrap(d.notes || '—', R, 8.2, CW - 16);
      const nh = Math.max(46, noteLines.length * 11 + 12);
      const sigH = sigImg ? 74 : 54;
      if (room() < 22 + 52 + nh + 24 + sigH + 40) { newPage(); header(); }
      TR('المراجع:', RX, y, B, 7, INK); TR(refs, RX - wid('المراجع:', B, 7) - 5, y, R, 7, SUB); y += 18;
      // summary tiles
      TR('الملخص', RX, y, B, 7.4, SUB); y += 12;
      const sw = CW / 4, na = d.count.na + d.count.blank;
      [[String(d.total), 'بند', INK], [String(d.count.ok), 'مطابق', OKC], [String(d.count.fail), 'غير مطابق', BADC], [String(na), d.count.blank ? 'لا ينطبق / لم يُحدد' : 'لا ينطبق', MUTE]]
        .forEach((t, i) => { const x = RX - (i + 1) * sw; box(x, y, sw, 34, null, LINE); TC(t[0], x + sw / 2, y + 5, B, 12.5, t[2]); TC(t[1], x + sw / 2, y + 22, R, 7.2, INK); });
      y += 34 + 14;
      TR('ملاحظات', RX, y, B, 7.4, SUB); y += 12;
      box(ML, y, CW, nh, null, LINE);
      noteLines.forEach((l, k) => TR(l, RX - 8, y + 6 + k * 11, R, 8.2, INK));
      y += nh + 14;
      // signatures (right to left): inspector, contractor, date
      y += sigImg ? 34 : 14;
      const sg = 10, s3 = (CW - 2 * sg) / 3;
      [['المفتش · ' + (d.inspector || ''), 0], ['ممثل المقاول', 1], ['التاريخ', 2]].forEach(s => {
        const x = RX - (s[1] + 1) * s3 - s[1] * sg;
        TR(s[0], x + s3 - 4, y - 11, R, 6.8, SUB); hl(x, x + s3, y, INK, 0.8);
        if (s[1] === 0 && sigImg) {
          const sh = 34, wS = Math.min(s3 - 8, sh * sigImg.width / sigImg.height), hS = wS * sigImg.height / sigImg.width;
          page.drawImage(sigImg, { x: x + s3 - 4 - wS, y: H - (y - 12), width: wS, height: hS });
        }
        if (s[1] === 2) TR(d.date || '', x + s3 - 4, y - 24, B, 8.6, INK);
      });
      y += 12;
      const disc = 'يجب تنفيذ الأعمال طبقًا لآخر إصدار معتمد من الرسومات والمواصفات الفنية وطرق التنفيذ المعتمدة. يتم فحص واعتماد الأعمال المخفية قبل تغطيتها، وإصلاح أي أعمال غير مطابقة وإعادة تقديمها للفحص. لا يعفي قبول الاستشاري المقاول من مسؤوليته عن مطابقة الأعمال لمتطلبات العقد.';
      if (room() > 30) wrap(disc, R, 6.2, CW).forEach(l => { TR(l, RX, y, R, 6.2, MUTE); y += 8.6; });
    }

    function photosPages() {
      if (!photos.length) return;
      const title = t => { TR(t, RX, y, B, 7.4, SUB); y += 12; };
      const ensure = (h, t) => { if (room() < h) { newPage(); header(); title(t + ' (تابع)'); } };
      const bef = photos.filter(p => p.tag === 'before'), aft = photos.filter(p => p.tag === 'after');
      const nP = Math.min(bef.length, aft.length), used = new Set(bef.slice(0, nP).concat(aft.slice(0, nP)));
      const gap = 10, pw = (CW - gap) / 2;
      const gridRows = (t, rows) => {
        if (!rows.length) return;
        if (room() < 130) { newPage(); header(); } else y += 18;
        title(t);
        rows.forEach(pair => {
          const hs = pair.map(c => c ? Math.min(240, pw * c.p.img.height / c.p.img.width) : 0), rowH = Math.max(...hs) + 14;
          ensure(rowH, t);
          pair.forEach((c, j) => {
            if (!c) return;
            const x = RX - pw - j * (pw + gap), w = hs[j] * c.p.img.width / c.p.img.height;
            box(x, y, pw, hs[j], CARD);
            page.drawImage(c.p.img, { x: x + (pw - w) / 2, y: H - y - hs[j], width: w, height: hs[j] });
            if (c.head) { const hw = wid(c.head, B, 7) + 12; box(x + pw - hw, y, hw, 13, c.head === 'قبل' ? SUB : OKC); TC(c.head, x + pw - hw / 2, y + 2.6, B, 7, WHITE); }
            TR(c.label, x + pw, y + hs[j] + 3, R, 6.8, SUB);
          });
          y += rowH + 6;
        });
      };
      const pairs = [];
      for (let k = 0; k < nP; k++) pairs.push([{ p: bef[k], head: 'قبل', label: 'قبل · ' + bef[k].cap }, { p: aft[k], head: 'بعد', label: 'بعد · ' + aft[k].cap }]);
      gridRows('قبل / بعد', pairs);
      const rest = photos.filter(p => !used.has(p)), rows = [];
      for (let k = 0; k < rest.length; k += 2) rows.push(rest.slice(k, k + 2).map(p => ({ p, label: (photos.indexOf(p) + 1) + ' · ' + (p.tag === 'before' ? 'قبل · ' : p.tag === 'after' ? 'بعد · ' : '') + p.cap })));
      gridRows('صور الموقع', rows);
    }

    firstPage(); checklist(); tail(); photosPages();

    let ptah = null;
    if (d.ptahSign) { try { ptah = await doc.embedPng(b64(PTAH_B64)); } catch (e) {} }
    pages.forEach((p, i) => {
      page = p;
      hl(ML, RX, FOOT_Y, LINE, 0.6);
      TR('مجموعة شاكر الاستشارية', RX, FOOT_Y + 6, R, 6.8, MUTE);
      TC('صفحة ' + (i + 1) + ' من ' + pages.length, W / 2, FOOT_Y + 6, B, 6.8, SUB);
      TL(d.cl.code + ' · ' + (d.irNumber || '') + ' · ساوث ميد', ML, FOOT_Y + 6, R, 6.4, MUTE);
      if (ptah && i === pages.length - 1) { const sh = 13, sw2 = sh * ptah.width / ptah.height; p.drawImage(ptah, { x: ML, y: FR + 22, width: sw2, height: sh }); }
    });
    doc.setTitle('طلب فحص واستلام ' + d.irNumber + ' · ' + d.cl.code);
    doc.setAuthor(d.inspector || ''); doc.setCreator('Shaker Inspect'); doc.setProducer('Shaker Inspect');
    return doc.save();
  }

  async function build(d, nodeLibs) { return draw(nodeLibs || await loadLibs(), d); }

  const api = { build, isFormCode };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else {
    root.ShakerForm = api;
    // wrap the English record builder: Shaker form for the activity checklists, the old record for everything else
    const PR = root.PtahRecord;
    if (PR && PR.build && !PR.build.__shaker) {
      const old = PR.build;
      PR.build = function (d, n) { return isFormCode(d) ? build(d, n) : old.call(PR, d, n); };
      PR.build.__shaker = true;
      // keep the ACC title (as written) on the prepared data so the form can print it
      const prep = PR.prepare;
      if (prep) PR.prepare = function (req, cl, marks) { const d = prep.call(PR, req, cl, marks); d.description = req.description || ''; return d; };
    }
  }
})(typeof window !== 'undefined' ? window : globalThis);
